const TOPICS=[{"s":"m","n":"Открытая вертикаль","w":"Разместить ладьи на открытой линии, усилить давление на слабую пешку или вторжение на 7-ю горизонталь.","b":"Оспорить линию разменом ладей или перекрыть её фигурой.","k":"Контроль открытой линии часто важнее немедленной атаки.","t":"Переход к ладейному эндшпилю после размена тяжёлых фигур."},{"s":"m","n":"Полуоткрытая вертикаль","w":"Поставить ладью напротив пешки соперника и усилить давление конём или ферзём.","b":"Защитить пешку, продвинуть её или закрыть линию.","k":"Полуоткрытая линия особенно полезна против изолированной пешки.","t":"При размене ферзей может возникнуть позиционный эндшпиль."},{"s":"m","n":"Слабая пешка","w":"Зафиксировать пешку на поле, где её трудно защитить, и атаковать её несколькими фигурами.","b":"Продвинуть слабую пешку, разменять атакующие фигуры или создать контригру.","k":"Не атаковать пешку одной фигурой: создавай несколько угроз.","t":"Выигрыш пешки часто переводит позицию в технический эндшпиль."},{"s":"m","n":"Изолированная пешка","w":"Использовать активность фигур и подготовить продвижение изолированной пешки.","b":"Блокировать пешку и атаковать её, особенно при упрощении позиции.","k":"Изолированная пешка может быть слабостью в эндшпиле, но источником активности в миттельшпиле.","t":"Размен ферзей обычно усиливает значение пешечной слабости."},{"s":"m","n":"Отсталая пешка","w":"Контролировать поле перед пешкой и давить по полуоткрытой линии.","b":"Продвинуть пешку при подходящем моменте или освободиться разменом.","k":"Поле перед отсталой пешкой часто становится сильным форпостом.","t":"Устойчивая отсталая пешка может стать целью в эндшпиле."},{"s":"m","n":"Сдвоенные пешки","w":"Использовать слабость пешечной структуры и открывшиеся линии.","b":"Создать активность фигур и не допустить фиксации слабых пешек.","k":"Сдвоенные пешки не всегда плохи: они могут контролировать важные поля.","t":"После размена фигур слабость структуры становится заметнее."},{"s":"m","n":"Пешечное большинство на ферзевом фланге","w":"Подготовить пешечное продвижение и создать проходную пешку.","b":"Блокировать большинство и активизировать короля/фигуры.","k":"Большинство имеет смысл только при поддержке фигур.","t":"Часто ведёт к пешечному или ладейному эндшпилю."},{"s":"m","n":"Пешечное большинство на королевском фланге","w":"Создать проходную пешку или пространство для атаки короля.","b":"Не допустить вскрытия короля и удерживать блокаду.","k":"Перед продвижением оцени безопасность собственного короля.","t":"Продвижение пешек может привести к разнофланговым проходным."},{"s":"m","n":"Форпост для коня","w":"Закрепить коня на защищённом поле, которое нельзя прогнать пешкой.","b":"Разменять коня или подготовить пешечный подрыв.","k":"Форпост особенно силён в центре и на поле перед слабой пешкой.","t":"Конь на форпосте часто сохраняет ценность даже в упрощённой позиции."},{"s":"m","n":"Плохой слон","w":"Ограничить собственные пешки на цвете слона и улучшить его диагональ.","b":"Зафиксировать пешки на цвете слона соперника.","k":"Плохой слон часто страдает из-за собственных пешек.","t":"Размен плохого слона может облегчить защиту эндшпиля."},{"s":"m","n":"Пара слонов","w":"Открыть позицию и создать диагонали для обоих слонов.","b":"Закрыть центр и найти устойчивые поля для коней.","k":"Пара слонов особенно сильна в открытых позициях.","t":"При упрощении до слонов против коней оцени структуру пешек."},{"s":"m","n":"Ограничение фигур","w":"Отнять у фигур соперника активные поля и ограничить их пешками.","b":"Искать освобождающий размен или пешечный прорыв.","k":"Ограниченная фигура часто хуже пассивной, но защищённой.","t":"Позиционное преимущество может сохраниться в эндшпиле."},{"s":"m","n":"Профилактика","w":"Предугадать план соперника и заранее затруднить его выполнение.","b":"Менять план и искать другой способ активизации.","k":"Сильный ход иногда не создаёт угрозу, а предотвращает её.","t":"Профилактика особенно важна в технических окончаниях."},{"s":"m","n":"Центральный пешечный прорыв","w":"Подготовить продвижение центральной пешки для открытия линий и диагоналей.","b":"Усилить контроль над полями прорыва и не допустить вскрытия позиции.","k":"Перед прорывом проверь тактические удары и безопасность короля.","t":"Вскрытие центра часто ускоряет переход к эндшпилю."},{"s":"m","n":"Атака на короля","w":"Подвести фигуры к королю, открыть линии и создать несколько угроз.","b":"Упростить позицию, закрыть линии или организовать контратаку.","k":"Атака успешна, когда в ней участвует несколько фигур.","t":"Размен ферзей обычно снижает непосредственную опасность."},{"s":"m","n":"Атака на рокированного короля","w":"Определить слабые поля вокруг рокировки и подготовить вскрытие линии.","b":"Не ослаблять пешки без необходимости и держать защитников рядом с королём.","k":"Не продвигай пешки перед своим королём без конкретной причины.","t":"Ослабленная пешечная защита может стать фактором эндшпиля."},{"s":"m","n":"Разнонаправленные рокировки","w":"Использовать пешечный штурм против короля соперника, сохраняя темп.","b":"Создать встречную игру и не позволить сопернику вскрыть линии первым.","k":"Темп имеет решающее значение при атаках на разных флангах.","t":"После размена ферзей атака обычно уступает место позиционной игре."},{"s":"m","n":"Жертва качества","w":"Получить за ладью лёгкую фигуру активность, пешки или сильную атаку.","b":"Сохранить координацию и не дать сопернику развить инициативу.","k":"Оцени компенсацию: активность, король, структура и проходные пешки.","t":"Жертва качества может привести к выгодному эндшпилю."},{"s":"m","n":"Тактическая связка","w":"Создать связку по линии или диагонали и усилить давление на связанную фигуру.","b":"Разорвать связку ходом короля/пешки или разменом атакующей фигуры.","k":"Связка сильна, если за ней следует конкретная угроза.","t":"Тактические размены могут резко упростить позицию."},{"s":"m","n":"Двойной удар","w":"Найти ход, который одновременно атакует две цели.","b":"Убрать одну из целей или создать более сильную встречную угрозу.","k":"Проверяй шахи, взятия и угрозы на каждом тактическом ходу.","t":"Выигрыш материала часто переводит игру в выигранный эндшпиль."},{"s":"m","n":"Открытое нападение","w":"Увести одну фигуру с линии, открыв удар второй фигуры.","b":"Изменить расположение цели или перекрыть линию.","k":"Скрытая фигура за атакующей фигурой может быть главным источником угрозы.","t":"Выигрыш фигуры часто ведёт к упрощению."},{"s":"m","n":"Отвлечение защитника","w":"Заставить ключевую фигуру покинуть поле или линию защиты.","b":"Сохранить защитника или создать ответную угрозу.","k":"Ищи фигуры, которые защищают сразу несколько важных объектов.","t":"Тактика может решить партию до эндшпиля."},{"s":"m","n":"Перегрузка фигуры","w":"Создать несколько угроз против фигуры, которая защищает слишком много объектов.","b":"Снять одну из обязанностей защитника или упростить позицию.","k":"Перегруженный защитник часто становится тактической мишенью.","t":"После выигрыша пешки или фигуры переходи к реализации."},{"s":"m","n":"Промежуточный ход","w":"Вставить шах или угрозу перед ожидаемым разменом.","b":"Проверить все промежуточные шахи и взятия до автоматического ответа.","k":"Не спеши отвечать на очевидное взятие: сначала проверь forcing moves.","t":"Промежуточный ход может изменить оценку переходящего эндшпиля."},{"s":"m","n":"Блокада проходной пешки","w":"Поставить фигуру перед проходной пешкой и ограничить её продвижение.","b":"Поддержать проходную королём и фигурами, вытесняя блокадёра.","k":"Конь часто хорошо блокирует пешки, но важна конкретная позиция.","t":"Типичный план в ладейных и лёгкофигурных окончаниях."},{"s":"m","n":"Создание проходной пешки","w":"Подготовить размены пешек, после которых одна пешка сможет пройти к превращению.","b":"Не допустить размена в пользу соперника и блокировать пешечную цепь.","k":"Дальняя проходная часто отвлекает короля соперника.","t":"Главная тема многих пешечных эндшпилей."},{"s":"m","n":"Пространственный перевес","w":"Сохранить пешки, ограничивающие фигуры соперника, и улучшить расположение фигур.","b":"Искать размены и освобождающие пешечные подрывы.","k":"Пространство полезно, если фигуры могут занять дополнительные поля.","t":"При разменах преимущество пространства может уменьшиться."},{"s":"m","n":"Манёвр коня","w":"Перевести коня на более сильное поле через промежуточные клетки.","b":"Не допустить закрепления коня и разменять его при выгодных условиях.","k":"Планируй маршрут коня, а не только следующий ход.","t":"Манёвры часто решают закрытые позиции."},{"s":"m","n":"Улучшение худшей фигуры","w":"Найти свою наименее активную фигуру и улучшить её положение.","b":"Не дать фигуре занять сильное поле, создавая темповые угрозы.","k":"Перед поиском комбинации проверь, можно ли просто улучшить фигуру.","t":"Позиционное улучшение особенно полезно в равных позициях."},{"s":"m","n":"Размен активной фигуры","w":"Разменять сильнейшую фигуру соперника, если это улучшает структуру или контроль полей.","b":"Избежать выгодного сопернику размена и сохранить активность.","k":"Размен оценивается по позиции после него, а не по номиналу фигур.","t":"Правильный размен может привести к технически выигранному окончанию."},{"s":"e","n":"Король и пешка против короля","w":"Подвести короля перед пешкой, занять оппозицию и провести пешку.","b":"Занять оппозицию или попасть в квадрат пешки.","k":"Правило квадрата и оппозиция — базовые инструменты пешечного эндшпиля.","t":"Пешечное окончание."},{"s":"e","n":"Оппозиция королей","w":"Занять позицию напротив короля соперника с нечётным числом полей между ними.","b":"Сохранить оппозицию или обойти короля сбоку.","k":"Оппозиция помогает королю пройти на ключевые поля.","t":"Используется в пешечных окончаниях."},{"s":"e","n":"Дальняя проходная пешка","w":"Создать проходную на фланге, чтобы отвлечь короля соперника.","b":"Остановить проходную королём и не дать королю соперника проникнуть в центр.","k":"Дальняя проходная часто выигрывает темп для короля на другом фланге.","t":"Пешечный эндшпиль."},{"s":"e","n":"Защищённая проходная","w":"Поддерживать проходную пешку другой пешкой и продвигать её при поддержке короля.","b":"Блокировать её и атаковать поддерживающую пешку.","k":"Защищённая проходная ограничивает фигуры и короля соперника.","t":"Пешечный или лёгкофигурный эндшпиль."},{"s":"e","n":"Отдалённая проходная","w":"Создать проходную как можно дальше от основной группы пешек.","b":"Не допустить её появления или организовать блокаду.","k":"Король соперника может быть вынужден уйти далеко от центра.","t":"Пешечный эндшпиль."},{"s":"e","n":"Правило квадрата","w":"Определить, успевает ли король попасть в квадрат проходной пешки.","b":"Если король не попадает в квадрат, искать иной способ остановки пешки.","k":"Квадрат строится от пешки до последней горизонтали.","t":"Пешечный эндшпиль."},{"s":"e","n":"Ключевые поля пешки","w":"Подвести короля к ключевым полям перед пешкой, чтобы обеспечить продвижение.","b":"Не пустить короля на ключевые поля.","k":"Для центральной пешки ключевые поля зависят от её ряда и положения.","t":"Пешечный эндшпиль."},{"s":"e","n":"Ладья позади проходной","w":"Поставить ладью за своей проходной или за проходной соперника.","b":"Не позволить ладье занять активную позицию позади пешки.","k":"Ладья наиболее эффективна позади проходной пешки.","t":"Ладейный эндшпиль."},{"s":"e","n":"Активность ладьи","w":"Проникнуть ладьёй на 7-ю горизонталь, атаковать пешки и шаховать короля.","b":"Активизировать ладью и не допустить её вторжения.","k":"Активная ладья часто важнее лишней пешки.","t":"Ладейный эндшпиль."},{"s":"e","n":"Отсечение короля ладьёй","w":"Отрезать короля соперника по горизонтали или вертикали от зоны борьбы.","b":"Приблизить короля и не позволить ладье удерживать отсечение.","k":"Отсечённый король хуже участвует в защите проходной.","t":"Ладейный эндшпиль."},{"s":"e","n":"Мост Люцены","w":"В выигранной ладейной позиции построить укрытие королю от шахов и поддержать превращение пешки.","b":"Давать шахи с тыла и мешать построению моста.","k":"Классическая техника реализации лишней проходной пешки.","t":"Ладейный эндшпиль."},{"s":"e","n":"Позиция Филидора","w":"Удерживать ладью на третьей горизонтали и не позволять королю соперника выйти вперёд.","b":"Перевести короля перед пешкой и добиться продвижения.","k":"Классический оборонительный метод в ладейном окончании с пешкой против ладьи.","t":"Ладейный эндшпиль."},{"s":"e","n":"Ладья против пешки","w":"Активно шаховать короля и атаковать пешку с безопасной дистанции.","b":"Поддержать пешку королём и приблизить её к превращению.","k":"Положение королей и пешки определяет, можно ли остановить пешку.","t":"Ладейный эндшпиль."},{"s":"e","n":"Слон против коня","w":"Использовать дальнобойность слона в открытой позиции или поля коня в закрытой.","b":"Закрепить блокаду и занять устойчивые поля.","k":"Сила слона и коня зависит от структуры пешек и расположения королей.","t":"Лёгкофигурный эндшпиль."},{"s":"e","n":"Слон и пешки одного цвета","w":"Разместить пешки на полях противоположного цвета слону, если это возможно.","b":"Зафиксировать пешки на цвете слона и ограничить его.","k":"Слон может быть ограничен собственными пешками на его цвете.","t":"Слоновый эндшпиль."},{"s":"e","n":"Разноцветные слоны","w":"Создать проходную или использовать перевес пешек на одном фланге.","b":"Построить блокаду на полях цвета своего слона.","k":"При отсутствии других фигур разноцветные слоны часто дают хорошие шансы на ничью.","t":"Слоновый эндшпиль."},{"s":"e","n":"Одноцветные слоны","w":"Активизировать короля и создать слабости на обоих флангах.","b":"Сохранять блокаду и не допускать появления второй слабости.","k":"Активность королей и пешечная структура имеют большое значение.","t":"Слоновый эндшпиль."},{"s":"e","n":"Конь и проходная пешка","w":"Поддержать продвижение конём и королём, контролируя поля превращения.","b":"Блокировать пешку и ограничить коня.","k":"Конь плохо справляется с дальними пешками, если король далеко.","t":"Коневой эндшпиль."},{"s":"e","n":"Ферзевый эндшпиль","w":"Использовать шахи, активность ферзя и продвижение проходной.","b":"Держать короля в безопасности и избегать вечного шаха.","k":"Активность ферзя часто важнее материального перевеса в одну пешку.","t":"Ферзевый эндшпиль."},{"s":"e","n":"Ферзь против проходной пешки","w":"Шахами и блокадой остановить пешку, не допуская безопасного превращения.","b":"Поддержать пешку королём и фигурами.","k":"Результат зависит от положения короля и близости пешки к превращению.","t":"Ферзевый эндшпиль."},{"s":"e","n":"Ладья и пешка против ладьи","w":"Активизировать короля, ладью и создать проходную.","b":"Использовать активные шахи и построить оборонительную позицию.","k":"Техника зависит от расположения пешки, королей и ладей.","t":"Ладейный эндшпиль."},{"s":"e","n":"Две связанные проходные","w":"Продвигать пешки согласованно, чтобы одна защищала другую.","b":"Блокировать одну пешку и атаковать вторую.","k":"Связанные проходные особенно опасны при поддержке короля.","t":"Пешечный или ладейный эндшпиль."},{"s":"e","n":"Изолированная проходная","w":"Поддержать пешку королём и фигурами, используя её как отвлекающую угрозу.","b":"Поставить блокадёра и атаковать пешку сзади.","k":"Даже остановленная проходная может связывать силы соперника.","t":"Пешечный/фигурный эндшпиль."},{"s":"e","n":"Пешечный прорыв","w":"Подготовить размен пешек, который создаёт проходную.","b":"Рассчитать варианты разменов и не допустить выгодного прорыва.","k":"Считай форсированные пешечные ходы до конца: один темп решает исход.","t":"Пешечный эндшпиль."},{"s":"e","n":"Треугольник королём","w":"Сделать манёвр королём, чтобы передать ход сопернику и получить оппозицию.","b":"Не допустить обхода и удерживать ключевые поля.","k":"Треугольник — способ выиграть темп в пешечном окончании.","t":"Пешечный эндшпиль."},{"s":"e","n":"Ничейная крепость","w":"Построить устойчивую защиту, которую соперник не может прорвать.","b":"Не допустить создания второй слабости и сохранять точную расстановку.","k":"Материальный перевес не всегда означает выигрыш при невозможности проникновения.","t":"Технический эндшпиль."},{"s":"e","n":"Активный король","w":"Централизовать короля и использовать его как боевую фигуру.","b":"Не позволить королю проникнуть на ключевые поля.","k":"В эндшпиле король становится активной фигурой.","t":"Любой эндшпиль без опасности мата."},{"s":"e","n":"Слабости на двух флангах","w":"Создать вторую слабость, чтобы растянуть защиту соперника.","b":"Сохранять гибкую оборону и не допустить проникновения короля.","k":"Защита одной слабости часто возможна, двух — намного труднее.","t":"Позиционный эндшпиль."},{"s":"e","n":"Правило двух слабостей","w":"Сначала зафиксировать одну слабость, затем создать вторую на другом участке доски.","b":"Не допустить появления второй цели и активно контратаковать.","k":"Одна слабость часто защищается; две могут перегрузить защиту.","t":"Позиционный эндшпиль."},{"s":"e","n":"Мат ферзём и королём","w":"Оттеснить короля к краю доски и поставить мат при поддержке своего короля.","b":"Держаться ближе к центру и избегать загоняния к краю.","k":"Король и ферзь легко выигрывают против одинокого короля при правильной технике.","t":"Матовая техника."},{"s":"e","n":"Мат ладьёй и королём","w":"Отрезать короля ладьёй и постепенно оттеснить его к краю доски.","b":"Стараться оставаться в центре и не допускать координации короля и ладьи.","k":"Нужно использовать короля для ограничения полей.","t":"Матовая техника."}];
